private static void ExecuteMigrationFile(
    SqlConnection conn,
    string migrationId,
    string scriptName,
    string script,
    string checksum)
{
    using (SqlTransaction tx = conn.BeginTransaction())
    {
        try
        {
            foreach (string batch in SplitSqlBatches(script))
            {
                if (string.IsNullOrWhiteSpace(batch))
                    continue;

                using (var cmd = new SqlCommand(batch, conn, tx))
                {
                    cmd.CommandTimeout = GetCommandTimeoutSeconds();
                    cmd.ExecuteNonQuery();
                }
            }

            using (var cmd = new SqlCommand(@"
                INSERT INTO dbo.HR_SchemaMigrationHistory
                    (MigrationID, ScriptName, AppliedOn, AppliedBy, Checksum)
                VALUES
                    (@MigrationID, @ScriptName, GETDATE(), @AppliedBy, @Checksum)", conn, tx))
            {
                cmd.Parameters.AddWithValue("@MigrationID", migrationId);
                cmd.Parameters.AddWithValue("@ScriptName", scriptName);
                cmd.Parameters.AddWithValue("@AppliedBy", Environment.MachineName);
                cmd.Parameters.AddWithValue("@Checksum", checksum);
                cmd.ExecuteNonQuery();
            }

            tx.Commit();
        }
        catch
        {
            tx.Rollback();
            throw;
        }
    }
}

